package it.cavallium.rockserver.core.common.distributed;

import it.cavallium.rockserver.core.common.export.ExportJobs;
import java.io.*;
import java.time.Duration;
import java.util.*;

/** Canonical path-free frozen database export input. Capture always covers every roster domain. */
public final class DatabaseExportDefinition {
    public static final int MAX_BYTES=64*1024*1024;
    public record Domain(RangeDirectory directory,DistributedSchema schema,List<Long> selectedColumns){
        public Domain{Objects.requireNonNull(directory);Objects.requireNonNull(schema);schema.requireMatches(directory);var columns=new TreeSet<Long>(Long::compareUnsigned);for(long id:selectedColumns){schema.column(id);if(!columns.add(id))throw new IllegalArgumentException("Repeated export column");}selectedColumns=List.copyOf(columns);}
        public List<UUID> physicalColumns(){return selectedColumns.stream().map(id->schema.column(id).columnId()).sorted(RangeDirectoryCodec.UUID_ORDER).toList();}
    }
    private final UUID jobId,requestId;private final DatabaseDomainRoster roster;private final List<Domain> domains;private final ExportJobs.Limits limits;private final byte[] encoded;
    public DatabaseExportDefinition(UUID jobId,UUID requestId,DatabaseDomainRoster roster,Collection<Domain> domains,ExportJobs.Limits limits){
        this.jobId=Objects.requireNonNull(jobId);this.requestId=Objects.requireNonNull(requestId);this.roster=Objects.requireNonNull(roster);this.limits=Objects.requireNonNull(limits);this.domains=domains.stream().sorted(Comparator.comparing(d->d.directory().domainId(),RangeDirectoryCodec.UUID_ORDER)).toList();
        var covered=new HashSet<UUID>();var allColumns=new HashSet<Long>();int selected=0;for(var domain:this.domains){if(!covered.add(domain.directory().domainId()) || !roster.clusterId().equals(domain.schema().clusterId()) || !roster.databaseId().equals(domain.schema().databaseId()))throw new IllegalArgumentException("Export domain namespace changed");for(var column:domain.schema().columns())if(!allColumns.add(column.apiId()))throw new IllegalArgumentException("Ambiguous database API column identity");selected+=domain.selectedColumns().size();}if(!covered.equals(new HashSet<>(roster.domainIds())) || selected<1 || selected>ExportJobs.MAX_COLUMNS)throw new IllegalArgumentException("Incomplete export roster/selection");
        encoded=BackupData.bytes(out->{out.writeInt(0x44455844);BackupData.uuid(out,jobId);BackupData.uuid(out,requestId);BackupData.blob(out,roster.encode());writeLimits(out,limits);out.writeInt(this.domains.size());for(var domain:this.domains){BackupData.blob(out,RangeDirectoryCodec.encode(domain.directory()));BackupData.blob(out,DistributedSchemaCodec.encode(domain.schema()));out.writeInt(domain.selectedColumns().size());for(long column:domain.selectedColumns())out.writeLong(column);}},MAX_BYTES);
    }
    public UUID jobId(){return jobId;}public UUID requestId(){return requestId;}public DatabaseDomainRoster roster(){return roster;}public List<Domain> domains(){return domains;}public ExportJobs.Limits limits(){return limits;}public byte[] encode(){return encoded.clone();}public int encodedBytes(){return encoded.length;}public byte[] page(long offset,int maximum){if(offset<0 || offset>encoded.length || maximum<1)throw new IllegalArgumentException("Invalid export witness page");return Arrays.copyOfRange(encoded,(int)offset,(int)Math.min(encoded.length,offset+maximum));}public byte[] digest(){return BackupData.hash(encoded);}
    public Domain domain(UUID id){return domains.stream().filter(d->d.directory().domainId().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Unknown export domain"));}
    public List<Long> selectedColumns(){return domains.stream().flatMap(d->d.selectedColumns().stream()).sorted(Long::compareUnsigned).toList();}
    public void requireVector(DatabaseDomainRoster current,Collection<Domain> domains){var next=new DatabaseExportDefinition(jobId,requestId,current,domains,limits);if(!Arrays.equals(encoded,next.encoded))throw new IllegalArgumentException("Frozen database export input changed");}
    public static DatabaseExportDefinition decode(byte[] bytes){return BackupData.read(bytes,MAX_BYTES,in->{if(in.readInt()!=0x44455844)throw new IOException("Wrong export definition");UUID job=BackupData.uuid(in),request=BackupData.uuid(in);var roster=DatabaseDomainRoster.decode(BackupData.blob(in,DatabaseDomainRoster.MAX_BYTES));var limits=readLimits(in);int count=BackupData.count(in,DatabaseDomainRoster.MAX_DOMAINS);var domains=new ArrayList<Domain>();for(int n=0;n<count;n++){var directory=RangeDirectoryCodec.decode(BackupData.blob(in,RangeDirectoryCodec.MAX_ENCODED_BYTES));var schema=DistributedSchemaCodec.decode(BackupData.blob(in,DistributedSchemaCodec.MAX_BYTES));int selected=BackupData.count(in,ExportJobs.MAX_COLUMNS,8);var columns=new ArrayList<Long>();for(int c=0;c<selected;c++)columns.add(in.readLong());domains.add(new Domain(directory,schema,columns));}var result=new DatabaseExportDefinition(job,request,roster,domains,limits);BackupData.canonical(bytes,result.encoded);return result;});}
    private static void writeLimits(DataOutputStream out,ExportJobs.Limits limits)throws IOException{out.writeInt(limits.maximumChunks());out.writeLong(limits.maximumJournalBytes());out.writeLong(limits.maximumDiskBytes());out.writeInt(limits.maximumRows());out.writeLong(limits.maximumPayloadBytes());out.writeLong(limits.maximumFileBytes());out.writeLong(limits.maximumChunkDuration().toNanos());out.writeLong(limits.snapshotTtl().toMillis());}
    private static ExportJobs.Limits readLimits(DataInputStream in)throws IOException{return new ExportJobs.Limits(in.readInt(),in.readLong(),in.readLong(),in.readInt(),in.readLong(),in.readLong(),Duration.ofNanos(in.readLong()),Duration.ofMillis(in.readLong()));}
}
